   /*************************************************************************/

420    /* <InOut>                                                               */
   421    /*    face :: The font face.                                             */
   422    /*                                                                       */
   423    /* <Return>                                                              */
   424    /*    FreeType error code.  0 means success.                             */
   425    /*                                                                       */
   426    static FT_Error
   427    ft_var_load_hvar( TT_Face  face )
   428    {
   429      FT_Stream  stream = FT_FACE_STREAM( face );
   430      FT_Memory  memory = stream->memory;
   431
   432      GX_Blend  blend = face->blend;
   433
   434      FT_Error   error;
   435      FT_UShort  majorVersion;
   436      FT_UShort  minorVersion;
   437      FT_ULong   table_len;
   438      FT_ULong   table_offset;
   439      FT_ULong   store_offset;
   440      FT_ULong   map_offset;
   441
   442      FT_ULong*  dataOffsetArray = NULL;
   443
   444
   445      blend->hvar_loaded = TRUE;
   446
   447      FT_TRACE2(( "HVAR " ));
   448
   449      error = face->goto_table( face, TTAG_HVAR, stream, &table_len );
   450      if ( error )
   451      {
   452        FT_TRACE2(( "is missing\n" ));
   453        goto Exit;
   454      }
   455
   456      table_offset = FT_STREAM_POS();
   457
   458      if ( FT_READ_USHORT( majorVersion ) ||
   459           FT_READ_USHORT( minorVersion ) )
   460        goto Exit;
   461      if ( majorVersion != 1 )
   462      {
   463        FT_TRACE2(( "bad table version %d\n", majorVersion ));
   464        error = FT_THROW( Invalid_Table );
   465        goto Exit;
   466      }
   467
   468      if ( FT_READ_ULONG( store_offset ) ||
   469           FT_READ_ULONG( map_offset )   )
   470        goto Exit;
   471
   472      /* parse item variation store */
   473      {
   474        FT_UShort  format;
   475        FT_ULong   region_offset;
   476        FT_UInt    i, j, k;
   477        FT_UInt    shortDeltaCount;
   478
   479        GX_HVStore    itemStore;
   480        GX_HVarTable  hvarTable;
   481        GX_HVarData   hvarData;
   482
   483
   484        if ( FT_STREAM_SEEK( table_offset + store_offset ) ||
   485             FT_READ_USHORT( format )                      )
   486          goto Exit;
   487        if ( format != 1 )
   488        {
   489          FT_TRACE2(( "bad store format %d\n", format ));
   490          error = FT_THROW( Invalid_Table );
   491          goto Exit;
   492        }
   493
   494        if ( FT_NEW( blend->hvar_table ) )    /* allocate table at top level */
   495          goto Exit;
   496
   497        hvarTable = blend->hvar_table;
   498        itemStore = &hvarTable->itemStore;
   499
   500        /* read top level fields */
   501        if ( FT_READ_ULONG( region_offset )         ||
   502             FT_READ_USHORT( itemStore->dataCount ) )
   503          goto Exit;
   504
   505        /* make temporary copy of item variation data offsets; */
   506        /* we will parse region list first, then come back     */
   507        if ( FT_NEW_ARRAY( dataOffsetArray, itemStore->dataCount ) )
   508          goto Exit;
   509
   510        for ( i = 0; i < itemStore->dataCount; i++ )
   511        {
   512          if ( FT_READ_ULONG( dataOffsetArray[i] ) )
   513            goto Exit;
   514        }
   515
   516        /* parse array of region records (region list) */
   517        if ( FT_STREAM_SEEK( table_offset + store_offset + region_offset ) )
   518          goto Exit;
   519
   520        if ( FT_READ_USHORT( itemStore->axisCount )   ||
   521             FT_READ_USHORT( itemStore->regionCount ) )
   522          goto Exit;
   523
   524        if ( FT_NEW_ARRAY( itemStore->varRegionList, itemStore->regionCount ) )
   525          goto Exit;
   526
   527        for ( i = 0; i < itemStore->regionCount; i++ )
   528        {
   529          GX_AxisCoords  axisCoords;
   530
   531
   532          if ( FT_NEW_ARRAY( itemStore->varRegionList[i].axisList,
   533                             itemStore->axisCount ) )
   534            goto Exit;
   535
   536          axisCoords = itemStore->varRegionList[i].axisList;
   537
   538          for ( j = 0; j < itemStore->axisCount; j++ )
   539          {
   540            FT_Short  start, peak, end;
   541
   542
   543            if ( FT_READ_SHORT( start ) ||
   544                 FT_READ_SHORT( peak )  ||
   545                 FT_READ_SHORT( end )   )
   546              goto Exit;
   547
   548            axisCoords[j].startCoord = FT_fdot14ToFixed( start );
   549            axisCoords[j].peakCoord  = FT_fdot14ToFixed( peak );
   550            axisCoords[j].endCoord   = FT_fdot14ToFixed( end );
   551          }
   552        }
   553
   554        /* end of region list parse */
   555
   556        /* use dataOffsetArray now to parse varData items */
   557        if ( FT_NEW_ARRAY( itemStore->varData, itemStore->dataCount ) )
   558          goto Exit;
   559
   560        for ( i = 0; i < itemStore->dataCount; i++ )
   561        {
   562          hvarData = &itemStore->varData[i];
   563
   564          if ( FT_STREAM_SEEK( table_offset       +
   565                               store_offset       +
   566                               dataOffsetArray[i] ) )
   567            goto Exit;
   568
   569          if ( FT_READ_USHORT( hvarData->itemCount )      ||
   570               FT_READ_USHORT( shortDeltaCount )          ||
   571               FT_READ_USHORT( hvarData->regionIdxCount ) )
   572            goto Exit;
   573
   574          /* check some data consistency */
   575          if ( shortDeltaCount > hvarData->regionIdxCount )
   576          {
   577            FT_TRACE2(( "bad short count %d or region count %d\n",
   578                        shortDeltaCount,
   579                        hvarData->regionIdxCount ));
   580            error = FT_THROW( Invalid_Table );
   581            goto Exit;
   582          }
   583
   584          if ( hvarData->regionIdxCount > itemStore->regionCount )
   585          {
   586            FT_TRACE2(( "inconsistent regionCount %d in varData[%d]\n",
   587                        hvarData->regionIdxCount,
   588                        i ));
   589            error = FT_THROW( Invalid_Table );
   590            goto Exit;
   591          }
   592
   593          /* parse region indices */
   594          if ( FT_NEW_ARRAY( hvarData->regionIndices,
   595                             hvarData->regionIdxCount ) )
   596            goto Exit;
   597
   598          for ( j = 0; j < hvarData->regionIdxCount; j++ )
   599          {
   600            if ( FT_READ_USHORT( hvarData->regionIndices[j] ) )
   601              goto Exit;
   602
   603            if ( hvarData->regionIndices[j] >= itemStore->regionCount )
   604            {
   605              FT_TRACE2(( "bad region index %d\n",
   606                          hvarData->regionIndices[j] ));
   607              error = FT_THROW( Invalid_Table );
   608              goto Exit;
   609            }
   610          }
   611
   612          /* Parse delta set.                                                */
   613          /*                                                                 */
   614          /* On input, deltas are ( shortDeltaCount + regionIdxCount ) bytes */
   615          /* each; on output, deltas are expanded to `regionIdxCount' shorts */
   616          /* each.                                                           */
   617          if ( FT_NEW_ARRAY( hvarData->deltaSet,
   618                             hvarData->regionIdxCount * hvarData->itemCount ) )
   619            goto Exit;
   620
   621          /* the delta set is stored as a 2-dimensional array of shorts; */
   622          /* sign-extend signed bytes to signed shorts                   */
   623          for ( j = 0; j < hvarData->itemCount * hvarData->regionIdxCount; )
   624          {
   625            for ( k = 0; k < shortDeltaCount; k++, j++ )
   626            {
   627              /* read the short deltas */
   628              FT_Short  delta;
   629
   630
   631              if ( FT_READ_SHORT( delta ) )
   632                goto Exit;
   633
   634              hvarData->deltaSet[j] = delta;
   635            }
   636
   637            for ( ; k < hvarData->regionIdxCount; k++, j++ )
   638            {
   639              /* read the (signed) byte deltas */
   640              FT_Char  delta;
   641
   642
   643              if ( FT_READ_CHAR( delta ) )
   644                goto Exit;
   645
   646              hvarData->deltaSet[j] = delta;
   647            }
   648          }
   649        }
   650      }
   651
   652      /* end parse item variation store */
   653
   654      /* parse width map */
   655      {
   656        GX_WidthMap  widthMap;
   657
   658        FT_UShort  format;
   659        FT_UInt    entrySize;
   660        FT_UInt    innerBitCount;
   661        FT_UInt    innerIndexMask;
   662        FT_UInt    i, j;
   663
   664
   665        widthMap = &blend->hvar_table->widthMap;
   666
   667        if ( FT_READ_USHORT( format )             ||
   668             FT_READ_USHORT( widthMap->mapCount ) )
   669          goto Exit;
   670
   671        if ( format & 0xFFC0 )
   672        {
   673          FT_TRACE2(( "bad map format %d\n", format ));
   674          error = FT_THROW( Invalid_Table );
   675          goto Exit;
   676        }
   677
   678        /* bytes per entry: 1, 2, 3, or 4 */
   679        entrySize      = ( ( format & 0x0030 ) >> 4 ) + 1;
   680        innerBitCount  = ( format & 0x000F ) + 1;
   681        innerIndexMask = ( 1 << innerBitCount ) - 1;
   682
   683        if ( FT_NEW_ARRAY( widthMap->innerIndex, widthMap->mapCount ) )
   684          goto Exit;
   685
   686        if ( FT_NEW_ARRAY( widthMap->outerIndex, widthMap->mapCount ) )
   687          goto Exit;
   688
   689        for ( i = 0; i < widthMap->mapCount; i++ )
   690        {
   691          FT_UInt  mapData = 0;
   692          FT_UInt  outerIndex, innerIndex;
   693
   694
   695          /* read map data one unsigned byte at a time, big endian */
   696          for ( j = 0; j < entrySize; j++ )
   697          {
   698            FT_Byte  data;
   699
   700
   701            if ( FT_READ_BYTE( data ) )
   702              goto Exit;
   703
   704            mapData = ( mapData << 8 ) | data;
   705          }
   706
   707          outerIndex = mapData >> innerBitCount;
   708
   709          if ( outerIndex >= blend->hvar_table->itemStore.dataCount )
   710          {
   711            FT_TRACE2(( "outerIndex[%d] == %d out of range\n",
   712                        i,
   713                        outerIndex ));
   714            error = FT_THROW( Invalid_Table );
   715            goto Exit;
   716          }
   717
   718          widthMap->outerIndex[i] = outerIndex;
   719
   720          innerIndex = mapData & innerIndexMask;
   721
   722          if ( innerIndex >=
   723                 blend->hvar_table->itemStore.varData[outerIndex].itemCount )
   724          {
   725            FT_TRACE2(( "innerIndex[%d] == %d out of range\n",
   726                        i,
   727                        innerIndex ));
   728            error = FT_THROW( Invalid_Table );
   729              goto Exit;
   730          }
   731
   732          widthMap->innerIndex[i] = innerIndex;
   733        }
   734      }
   735
   736      /* end parse width map */
   737
   738      FT_TRACE2(( "loaded\n" ));
   739      error = FT_Err_Ok;
   740
   741    Exit:
   742      FT_FREE( dataOffsetArray );
   743
   744      if ( !error )
   745        blend->hvar_checked = TRUE;
   746
   747      return error;
   748    }
