   751    /*************************************************************************/
   752    /*                                                                       */
   753    /* <Function>                                                            */
   754    /*    tt_hadvance_adjust                                                 */
   755    /*                                                                       */
   756    /* <Description>                                                         */
   757    /*    Apply HVAR advance width adjustment of a given glyph.              */
   758    /*                                                                       */
   759    /* <Input>                                                               */
   760    /*    gindex :: The glyph index.                                         */
   761    /*                                                                       */
   762    /* <InOut>                                                               */
   763    /*    face   :: The font face.                                           */
   764    /*                                                                       */
   765    /*    adelta :: Points to width value that gets modified.                */
   766    /*                                                                       */
   767    FT_LOCAL_DEF( FT_Error )
   768    tt_hadvance_adjust( TT_Face  face,
   769                        FT_UInt  gindex,
   770                        FT_Int  *avalue )
   771    {
   772      FT_Error  error = FT_Err_Ok;
   773
   774      GX_HVarData  varData;
   775
   776      FT_UInt    innerIndex, outerIndex;
   777      FT_UInt    master, j;
   778      FT_Fixed   netAdjustment = 0;     /* accumulated adjustment */
   779      FT_Fixed   scaledDelta;
   780      FT_Short*  deltaSet;
   781      FT_Fixed   delta;
   782
   783
   784      if ( !face->blend )
   785        goto Exit;
   786
   787      if ( !face->blend->hvar_loaded )
   788      {
   789        /* initialize hvar table */
   790        face->blend->hvar_error = ft_var_load_hvar( face );
   791      }
   792
   793      if ( !face->blend->hvar_checked )
   794      {
   795        error = face->blend->hvar_error;
   796        goto Exit;
   797      }
   798
   799      if ( gindex >= face->blend->hvar_table->widthMap.mapCount )
   800      {
   801        FT_TRACE2(( "gindex %d out of range\n", gindex ));
   802        error = FT_THROW( Invalid_Argument );
   803        goto Exit;
   804      }
   805
   806      /* trust that HVAR parser has checked indices */
   807      outerIndex = face->blend->hvar_table->widthMap.outerIndex[gindex];
