    67    static int
    68    archive_read_entry_data( struct archive   *ar,
    69                             vector<FT_Byte>  *vw )
    70    {
    71      int             r;
    72      const FT_Byte*  buff;
    73      size_t          size;
    74      int64_t         offset;
    75
    76      for (;;)
    77      {
    78        r = archive_read_data_block( ar,
    79                                     reinterpret_cast<const void**>( &buff ),
    80                                     &size,
    81                                     &offset );
    82        if ( r == ARCHIVE_EOF )
    83          return ARCHIVE_OK;
    84        if ( r != ARCHIVE_OK )
    85          return r;
    86
    87        vw->insert( vw->end(), buff, buff + size );
    88      }
    89    }
